from __future__ import annotations

from pathlib import Path


def render_test_kernel_py(entry_dir: Path, target: str | None = None) -> str:
    """Generate test_kernel.py that validates the .so against graph.forward."""
    if target == "mppa":
        return _render_mppa_test_kernel_py()
    return f'''\
#
# SPDX-License-Identifier: BSD-3-Clause
# Generated by xtc.kernelbase — validates compiled kernel vs graph.forward.
#
from pathlib import Path

import yaml

from xtc.graphs.xtc.builder import graph_builder
from xtc.targets.host.HostModule import HostModule

_ENTRY = Path(__file__).resolve().parent


def _load_meta() -> dict:
    with open(_ENTRY / "meta.yaml", encoding="utf-8") as f:
        return yaml.safe_load(f)


def test_kernel_matches_reference() -> None:
    graph = graph_builder.graph_from_file(_ENTRY / "graph.yaml")
    meta = _load_meta()
    payload_name = meta["payload_name"]
    kernel_path = _ENTRY / "kernel.so"
    assert kernel_path.is_file(), f"missing {{kernel_path}}"

    mod = HostModule(
        meta.get("graph_name") or graph.name or "kernel",
        payload_name,
        str(kernel_path),
        "shlib",
        graph=graph,
    )
    code = mod.get_executor(validate=True).execute()
    assert code == 0, f"validation failed with code {{code}}"


if __name__ == "__main__":
    test_kernel_matches_reference()
    print("OK")
'''


def _render_mppa_test_kernel_py() -> str:
    """Generate test_kernel.py that runs the MPPA kernel against graph.forward."""
    return '''\
#
# SPDX-License-Identifier: BSD-3-Clause
# Generated by xtc.kernelbase — validates the compiled MPPA kernel vs graph.forward.
#
from pathlib import Path

import yaml

from xtc.graphs.xtc.builder import graph_builder
from xtc.runtimes.accelerator.mppa import MppaDevice
from xtc.targets.accelerator.mppa.MppaModule import MppaModule

_ENTRY = Path(__file__).resolve().parent


def _load_meta():
    with open(_ENTRY / "meta.yaml", encoding="utf-8") as f:
        return yaml.safe_load(f)


def test_kernel_matches_reference() -> None:
    graph = graph_builder.graph_from_file(_ENTRY / "graph.yaml")
    meta = _load_meta()
    kernel_path = _ENTRY / "kernel.so"
    assert kernel_path.is_file(), f"missing {kernel_path}"

    # graph.yaml does not store tensor placement: all tensors of an MPPA kernel live on the device
    device = MppaDevice()
    for t in [*graph.inputs_types, *graph.outputs_types]:
        t._device = device

    mod = MppaModule(
        meta.get("graph_name") or graph.name or "kernel",
        meta["payload_name"],
        str(kernel_path),
        "shlib",
        device.config,
        graph=graph,
    )
    code = mod.get_executor(validate=True).execute()
    assert code == 0, f"validation failed with code {code}"


if __name__ == "__main__":
    test_kernel_matches_reference()
    print("OK")
'''
